WITH cleaned AS (SELECT id, store_name, city, opened_date, sqft, SUBSTRING(store_name, 1, 3) AS store_name_prefix, INITCAP(TRIM(region)) AS region_title, COALESCE(region, 'N/A') AS region_filled FROM stores WHERE LENGTH(store_name) < 12 AND opened_date > TO_DATE('2023-07-10')), with_windows AS (SELECT *, ROUND(sqft / SUM(sqft) OVER (PARTITION BY city), 4) AS sqft_share, LAG(sqft, 2, 0) OVER (ORDER BY opened_date, id) AS prev_sqft FROM cleaned), scored AS (SELECT *, LAST_VALUE(sqft_share, TRUE) OVER (PARTITION BY city ORDER BY opened_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_sqft_share, CUME_DIST() OVER w_running AS sqft_share_cume_dist FROM with_windows WINDOW w_running AS (PARTITION BY city ORDER BY sqft_share DESC NULLS LAST)), scored_stores AS (SELECT *, MIN(sqft_share_cume_dist) OVER (PARTITION BY city ORDER BY sqft_share, id ROWS BETWEEN 3 PRECEDING AND CURRENT ROW) AS last4_min_sqft_share_cume_dist, AVG(sqft_share_cume_dist) OVER (PARTITION BY city ORDER BY sqft_share, id ROWS BETWEEN 3 PRECEDING AND CURRENT ROW) AS last4_avg_sqft_share_cume_dist, SUM(sqft_share_cume_dist) OVER (PARTITION BY city ORDER BY sqft_share, id ROWS BETWEEN 3 PRECEDING AND CURRENT ROW) AS last4_sum_sqft_share_cume_dist, MAX(sqft_share_cume_dist) OVER (PARTITION BY city ORDER BY sqft_share, id ROWS BETWEEN 3 PRECEDING AND CURRENT ROW) AS last4_max_sqft_share_cume_dist FROM scored WHERE sqft = 6416), latest AS (SELECT * FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY city ORDER BY opened_date NULLS LAST, id) AS rank_in_group FROM scored_stores) t WHERE rank_in_group = 1), grouped AS (SELECT city, ROUND(SUM(sqft_share_cume_dist) / NULLIF(COUNT(CASE WHEN city = 'New York' THEN 1 END), 0), 2) AS sqft_share_cume_dist_per_new_york, AVG(sqft) FILTER (WHERE city = 'New York') AS new_york_avg_sqft, COUNT(CASE WHEN city = 'London' THEN 1 END) AS london_count, ROUND(AVG(sqft_share_cume_dist), 2) AS avg_sqft_share_cume_dist, COUNT(CASE WHEN city = 'London' THEN 1 END) AS london_count_2, APPROX_PERCENTILE(last_known_sqft_share, ARRAY(0.25, 0.5, 0.75)) AS last_known_sqft_share_quartiles FROM latest GROUP BY 1) SELECT city, sqft_share_cume_dist_per_new_york, london_count_2, CASE WHEN city RLIKE '^(New York|Tokyo)$' THEN 'EXTENDED' WHEN city RLIKE '^(Bangkok|Chiang Mai)$' THEN 'CORE' ELSE 'GROUP_A' END AS city_zone FROM grouped;
